-- R3D-6 bounded workflow/AI state; existing outbox and workers own transport.
CREATE TABLE automation_workflows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,actor_id uuid NOT NULL,definition jsonb NOT NULL,revision bigint NOT NULL DEFAULT 1,operation_key text NOT NULL,fingerprint text NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(bot_id,operation_key),UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id),FOREIGN KEY(workspace_id,actor_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE TABLE automation_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,workflow_id uuid NOT NULL,event_id text NOT NULL,actor_id uuid NOT NULL,snapshot jsonb NOT NULL,event jsonb NOT NULL,state text NOT NULL CHECK(state IN('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','SKIPPED')),action_index int NOT NULL DEFAULT 0,attempt int NOT NULL DEFAULT 1,results jsonb NOT NULL DEFAULT '[]',result jsonb NOT NULL DEFAULT '{}',code text NOT NULL DEFAULT '',available_at timestamptz NOT NULL,started_at timestamptz,completed_at timestamptz,lease_until timestamptz,created_at timestamptz NOT NULL,UNIQUE(workflow_id,event_id),FOREIGN KEY(workflow_id,workspace_id,bot_id) REFERENCES automation_workflows(id,workspace_id,bot_id),FOREIGN KEY(workspace_id,actor_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX automation_dispatch ON automation_executions(workspace_id,state,available_at,id);
CREATE TABLE ai_models(id text PRIMARY KEY,definition jsonb NOT NULL,endpoint text NOT NULL,key_id text NOT NULL,encrypted_key bytea NOT NULL,revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL);
CREATE TABLE ai_configurations(workspace_id uuid NOT NULL,bot_id uuid NOT NULL,definition jsonb NOT NULL,revision bigint NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE TABLE ai_knowledge(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4096),enabled bool NOT NULL,revision bigint NOT NULL DEFAULT 1,operation_key text NOT NULL,fingerprint text NOT NULL,UNIQUE(bot_id,operation_key),UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
CREATE INDEX ai_knowledge_search ON ai_knowledge USING gin(to_tsvector('simple',body));
CREATE TABLE ai_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,subject text NOT NULL,contact_id uuid,context jsonb NOT NULL DEFAULT '[]',revision bigint NOT NULL DEFAULT 1,UNIQUE(bot_id,subject),UNIQUE(id,workspace_id,bot_id),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id),FOREIGN KEY(contact_id,workspace_id,bot_id) REFERENCES crm_contacts(id,workspace_id,bot_id));
CREATE TABLE ai_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,thread_id uuid NOT NULL,actor_id uuid NOT NULL,operation_key text NOT NULL,fingerprint text NOT NULL,state text NOT NULL CHECK(state IN('SENDING','SUCCEEDED','FAILED','UNKNOWN')),code text NOT NULL DEFAULT '',result jsonb NOT NULL DEFAULT '{}',model_id text NOT NULL,attempt int NOT NULL DEFAULT 1,input_tokens bigint NOT NULL DEFAULT 0 CHECK(input_tokens>=0),output_tokens bigint NOT NULL DEFAULT 0 CHECK(output_tokens>=0),tool_calls int NOT NULL DEFAULT 0 CHECK(tool_calls BETWEEN 0 AND 8),created_at timestamptz NOT NULL,completed_at timestamptz,latency_ms bigint NOT NULL DEFAULT 0 CHECK(latency_ms>=0),delivery text NOT NULL DEFAULT 'NONE' CHECK(delivery IN('NONE','SENDING','SENT','FAILED','UNKNOWN')),UNIQUE(bot_id,operation_key),FOREIGN KEY(thread_id,workspace_id,bot_id) REFERENCES ai_threads(id,workspace_id,bot_id),FOREIGN KEY(workspace_id,actor_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX ai_history ON ai_requests(workspace_id,bot_id,id);
CREATE FUNCTION guard_intelligence_definition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'intelligence retention requires explicit policy'; END IF;
 IF NEW.workspace_id<>OLD.workspace_id OR NEW.bot_id<>OLD.bot_id OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'scope/revision invalid'; END IF;
 RETURN NEW;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['automation_workflows','automation_executions','ai_configurations','ai_knowledge','ai_threads','ai_requests'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_scope ON %I USING(workspace_id::text=current_setting(''app.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''app.workspace_id'',true))',t);
 IF t IN('automation_workflows','ai_configurations','ai_knowledge','ai_threads') THEN EXECUTE format('CREATE TRIGGER intelligence_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION guard_intelligence_definition()',t); END IF;
END LOOP;END $$;
INSERT INTO permissions(key) VALUES('automation.manage'),('ai.manage'),('ai.invoke');
INSERT INTO role_permissions(role_key,permission_key) SELECT r,p FROM (VALUES('OWNER'),('ADMIN')) a(r) CROSS JOIN (VALUES('automation.manage'),('ai.manage'),('ai.invoke')) b(p);
INSERT INTO role_permissions(role_key,permission_key) VALUES('SUPPORT_AGENT','ai.invoke');
INSERT INTO commercial_catalog(kind,key,version,enabled,effective_at,definition,reason)
 SELECT 'PLUGIN',key,1,true,'2020-01-01T00:00:00Z',jsonb_build_object('plugin',jsonb_build_object('capabilities',caps,'sale_enabled',false,'scope','PER_BOT','prices',jsonb_build_object('daily',jsonb_build_object('unit','USD','scale',2,'amount','0'),'monthly',jsonb_build_object('unit','USD','scale',2,'amount','0')),'trial',jsonb_build_object('enabled',false,'duration_seconds',0),'grace_seconds',0)), 'R3D-6 configure before sale; no automatic grants'
 FROM (VALUES('automation','["workflow.execute","telegram.send"]'::jsonb),('ai-assistant','["ai.invoke","telegram.send"]'::jsonb)) p(key,caps);
INSERT INTO commercial_catalog(kind,key,version,enabled,effective_at,definition,reason)
 SELECT 'QUOTA',key,1,true,'2020-01-01T00:00:00Z',jsonb_build_object('quota',jsonb_build_object('scope','PER_BOT','reset',period,'default',jsonb_build_object('value','0','unlimited',true))), 'R3D-6 configurable quota'
 FROM (VALUES('automation.workflows.count','NONE'),('automation.executions.monthly','MONTHLY'),('ai.requests.monthly','MONTHLY'),('ai.input_tokens.monthly','MONTHLY'),('ai.output_tokens.monthly','MONTHLY'),('ai.tool_calls.monthly','MONTHLY')) q(key,period);
CREATE TABLE intelligence_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,bot_id uuid NOT NULL,operation_key text NOT NULL,fingerprint text NOT NULL,state text NOT NULL CHECK(state IN('SENDING','SENT','FAILED','UNKNOWN')),created_at timestamptz NOT NULL,completed_at timestamptz,UNIQUE(bot_id,operation_key),FOREIGN KEY(bot_id,workspace_id) REFERENCES customer_bots(id,workspace_id));
ALTER TABLE intelligence_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE intelligence_deliveries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON intelligence_deliveries USING(workspace_id::text=current_setting('app.workspace_id',true)) WITH CHECK(workspace_id::text=current_setting('app.workspace_id',true));
